import heapq


def _build_interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        if len(mandatory) > k or mandatory & blocked:
            return {"error": "impossible"}

        best_ids = None
        best_value = None
        n = len(jobs)
        for mask in range(1 << n):
            if mask.bit_count() != k:
                continue
            selected = [jobs[i] for i in range(n) if mask & (1 << i)]
            ids = {job["id"] for job in selected}
            if ids & blocked or not mandatory.issubset(ids):
                continue

            counts = {}
            for job in selected:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active = []
            compatible = True
            for job in sorted(selected, key=lambda row: (row["start"], row["end"], row["id"])):
                while active and active[0] <= job["start"]:
                    heapq.heappop(active)
                heapq.heappush(active, job["end"])
                if len(active) > capacity:
                    compatible = False
                    break
            if not compatible:
                continue

            id_list = sorted(ids)
            value = sum(job["value"] for job in selected)
            if (best_ids is None or value > best_value or
                (value == best_value and
                 ((tie == "smallest" and id_list < best_ids) or
                  (tie == "largest" and id_list > best_ids)))):
                best_ids, best_value = id_list, value

        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]

        choices = []
        for name in names:
            rows = packages[name]
            choices.append([None] + [row for row in rows
                                     if row["version"] not in blocked.get(name, [])
                                     and (name not in pins or row["version"] == pins[name])])

        best_vector = None
        best_versions = None
        for assignment in product(*choices):
            installed = {name: row for name, row in zip(names, assignment)
                         if row is not None}
            if any(name not in installed or
                   not low <= installed[name]["version"] <= high
                   for name, (low, high) in roots.items()):
                continue

            edges = {name: [] for name in installed}
            valid = True
            for name, row in installed.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    if other not in installed or not dep["min"] <= installed[other]["version"] <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            reached = set()
            active = set()
            finished = set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                reached.add(name)
                for other in edges[name]:
                    if not visit(other):
                        return False
                active.remove(name)
                finished.add(name)
                return True

            for root in roots:
                if not visit(root):
                    valid = False
                    break
            if not valid or reached != set(installed):
                continue

            vector = tuple(installed[name]["version"] if name in installed else -1
                           for name in sorted(names, reverse=True))
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: row["version"] for name, row in installed.items()}

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        indices = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        start_mask = indices.get(source, 0)
        initial = (source, start_mask, 0)
        start_time = data["start"]
        dist = {initial: start_time}
        queue = [(start_time, source, start_mask, 0)]
        coupon_count = data["coupons"]

        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full and used == coupon_count:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < coupon_count:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                next_node = edge["v"]
                next_mask = mask | indices.get(next_node, 0)
                for duration, next_used in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_state = (next_node, next_mask, next_used)
                    if arrival < dist.get(next_state, float("inf")):
                        dist[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
        return {"arrival": None}
    return solve


